/**
 * with-graine-fcm — Android hosted ringing for any Expo app that uses @graineai/inapp-react-native-calls.
 *
 * When your workspace lets Graine ring your users (Workspace settings → In-app calling, with your
 * Firebase service account uploaded), a booked call arrives on Android as a high-priority FCM data
 * message. It must reach the SDK natively — so it rings even when the app was closed and before any
 * JavaScript runs — and the SDK must have this install's FCM token to register the device with
 * Graine. This plugin does exactly that, at `expo prebuild`:
 *
 *   1. writes  android/app/src/main/java/<package>/graine/<serviceName>.kt — a FirebaseMessagingService:
 *        onNewToken(token)        → GraineCallsHost.onNewToken(context, token)
 *        onMessageReceived(msg)   → GraineCallsHost.handlePush(context, msg.data)  (true = it was a call)
 *      plus syncToken(context), which hands over the current token at launch (an install whose token
 *      was issued before this service existed never gets onNewToken again);
 *   2. declares the service in AndroidManifest.xml for com.google.firebase.MESSAGING_EVENT;
 *   3. adds com.google.firebase:firebase-messaging to android/app/build.gradle;
 *   4. calls syncToken(this) after super.onCreate() in MainApplication.kt (syncTokenOnLaunch);
 *   5. keeps android.permission.USE_FULL_SCREEN_INTENT (the ringing call screen over the lock screen)
 *      even if another plugin or `blockedPermissions` tried to remove it.
 *
 * Use:
 *   // app.config.ts — and set android.googleServicesFile to your google-services.json
 *   plugins: [["./plugins/with-graine-fcm", { serviceName: "GraineMessagingService" }]]
 *
 * Options (all optional):
 *   serviceName                Kotlin class name                         default "GraineMessagingService"
 *   firebaseMessagingVersion   com.google.firebase:firebase-messaging     default "24.1.2"
 *   syncTokenOnLaunch          hand the token over at every launch        default true
 *   priority                   intent-filter priority for MESSAGING_EVENT default 10
 *
 * Already have a FirebaseMessagingService (for example @react-native-firebase/messaging)? Android
 * delivers each push to ONE service, so do not add a second: leave this plugin out and forward from
 * yours — GraineCallsHost.onNewToken(this, token) in onNewToken and
 * `if (GraineCallsHost.handlePush(this, message.data)) return` first thing in onMessageReceived.
 *
 * Without a google-services.json the app still builds and runs; Firebase is simply not started, the
 * service is never called, and syncToken does nothing. iOS needs no plugin: VoIP pushes reach the SDK
 * through PushKit (see GraineCalls.enableVoIPPushes).
 */
const fs = require("fs");
const path = require("path");
const {
  AndroidConfig,
  createRunOncePlugin,
  withAndroidManifest,
  withAppBuildGradle,
  withDangerousMod,
  withMainApplication,
} = require("expo/config-plugins");

const FULL_SCREEN_INTENT = "android.permission.USE_FULL_SCREEN_INTENT";
const MESSAGING_EVENT = "com.google.firebase.MESSAGING_EVENT";
const MARK = "with-graine-fcm";

const DEFAULTS = {
  serviceName: "GraineMessagingService",
  firebaseMessagingVersion: "24.1.2",
  syncTokenOnLaunch: true,
  priority: 10,
};

function options(raw) {
  const o = { ...DEFAULTS, ...(raw || {}) };
  if (!/^[A-Z][A-Za-z0-9_]*$/.test(o.serviceName)) throw new Error(`${MARK}: serviceName must be a Kotlin class name, got "${o.serviceName}"`);
  if (!/^[0-9][0-9A-Za-z.+-]*$/.test(String(o.firebaseMessagingVersion))) throw new Error(`${MARK}: firebaseMessagingVersion looks wrong: "${o.firebaseMessagingVersion}"`);
  return o;
}

function packageOf(config) {
  const pkg = AndroidConfig.Package.getPackage(config);
  if (!pkg) throw new Error(`${MARK}: set android.package in the app config`);
  return pkg;
}

/** The Kotlin source. Generated, so every app gets the same two forwarding lines. */
function serviceSource(pkg, o) {
  return `package ${pkg}.graine

import android.content.Context
import android.util.Log
import ai.graine.inapp.GraineCallsHost
import com.google.firebase.FirebaseApp
import com.google.firebase.messaging.FirebaseMessaging
import com.google.firebase.messaging.FirebaseMessagingService
import com.google.firebase.messaging.RemoteMessage

/**
 * Generated by plugins/with-graine-fcm.js at expo prebuild — change the plugin, not this file.
 *
 * Hands this install's FCM token and every push to the Graine call engine, natively: a call Graine
 * rings arrives as a data message and rings even when the app was closed, before any JavaScript runs.
 */
class ${o.serviceName} : FirebaseMessagingService() {
    override fun onNewToken(token: String) {
        GraineCallsHost.onNewToken(this, token)
    }

    override fun onMessageReceived(message: RemoteMessage) {
        if (GraineCallsHost.handlePush(this, message.data)) return
        // Not a call. This app sends no other pushes; an app that does handles them here.
    }

    companion object {
        /** The current token, at launch: an install whose token predates this service never sees onNewToken again. */
        @JvmStatic
        fun syncToken(context: Context) {
            try {
                if (FirebaseApp.getApps(context).isEmpty()) return // no google-services.json: nothing to do
                FirebaseMessaging.getInstance().token.addOnSuccessListener { token ->
                    if (!token.isNullOrEmpty()) GraineCallsHost.onNewToken(context.applicationContext, token)
                }
            } catch (e: Exception) {
                Log.w("GraineCalls", "No push token yet: \${e.message}")
            }
        }
    }
}
`;
}

const withServiceSource = (config, o) =>
  withDangerousMod(config, [
    "android",
    async (cfg) => {
      const pkg = packageOf(cfg);
      const dir = path.join(cfg.modRequest.platformProjectRoot, "app", "src", "main", "java", ...pkg.split("."), "graine");
      fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(path.join(dir, `${o.serviceName}.kt`), serviceSource(pkg, o));
      return cfg;
    },
  ]);

const withServiceInManifest = (config, o) =>
  withAndroidManifest(config, (cfg) => {
    const manifest = cfg.modResults.manifest;
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(cfg.modResults);
    const name = `${packageOf(cfg)}.graine.${o.serviceName}`;
    app.service = (app.service || []).filter((s) => s.$["android:name"] !== name);
    app.service.push({
      $: { "android:name": name, "android:exported": "false" },
      "intent-filter": [{ $: { "android:priority": String(o.priority) }, action: [{ $: { "android:name": MESSAGING_EVENT } }] }],
    });
    // The ringing call screen needs it; a removal elsewhere would silence rings on a locked phone.
    const perms = (manifest["uses-permission"] || []).filter(
      (p) => !(p.$["android:name"] === FULL_SCREEN_INTENT && p.$["tools:node"] === "remove"),
    );
    if (!perms.some((p) => p.$["android:name"] === FULL_SCREEN_INTENT)) perms.push({ $: { "android:name": FULL_SCREEN_INTENT } });
    manifest["uses-permission"] = perms;
    return cfg;
  });

const withMessagingDependency = (config, o) =>
  withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== "groovy" && cfg.modResults.language !== "kt") return cfg;
    const contents = cfg.modResults.contents;
    if (contents.includes("com.google.firebase:firebase-messaging")) return cfg;
    const line = `implementation("com.google.firebase:firebase-messaging:${o.firebaseMessagingVersion}")`;
    const next = contents.replace(/^dependencies\s*\{/m, (m) => `${m}\n    // ${MARK}: the messaging service that hands call pushes to the Graine SDK\n    ${line}`);
    if (next === contents) throw new Error(`${MARK}: no top-level dependencies { } block in android/app/build.gradle`);
    cfg.modResults.contents = next;
    return cfg;
  });

const withTokenSyncAtLaunch = (config, o) =>
  withMainApplication(config, (cfg) => {
    if (!o.syncTokenOnLaunch) return cfg;
    const call = `${packageOf(cfg)}.graine.${o.serviceName}.syncToken(this)`;
    const contents = cfg.modResults.contents;
    if (contents.includes(call)) return cfg;
    const semi = cfg.modResults.language === "java" ? ";" : "";
    // Right after super.onCreate(): only the call itself is matched, so the line after it stays where it was.
    const next = contents.replace(/super\.onCreate\(\);?/, (m) => `${m}\n    // ${MARK}: hand the current push token to the Graine SDK\n    ${call}${semi}`);
    if (next === contents) throw new Error(`${MARK}: could not find super.onCreate() in MainApplication`);
    cfg.modResults.contents = next;
    return cfg;
  });

function withGraineFcm(config, raw) {
  const o = options(raw);
  config = withServiceSource(config, o);
  config = withServiceInManifest(config, o);
  config = withMessagingDependency(config, o);
  config = withTokenSyncAtLaunch(config, o);
  return config;
}

module.exports = createRunOncePlugin(withGraineFcm, MARK, "1.0.0");
module.exports.serviceSource = serviceSource;
